import { CaptureEventIds, CaptureEventTypes } from './gen/eventIds';

export class CaptureEvent<T> {
  id: CaptureEventIds;
  type: CaptureEventTypes;
  result: number;
  value?: T;
  constructor(id: CaptureEventIds, type: CaptureEventTypes, result: number = 0, value?: T) {
    this.id = id;
    this.type = type;
    this.result = result;
    if(value) {
      this.value = value;
    }
  }
}
