export class CaptureEventResult<T> {
  handle?: number;
  event: CaptureEvent<T>;
  constructor(id: CaptureEventIds, type: CaptureEventTypes, result: number, value: T, handle?: number) {
    this.event = new CaptureEvent<T>(id, type, result, value);
    if(handle) {
      this.handle = handle;
    }
  }
}

export class JRpcEvent<T> {
  jsonrpc: string = '2.0';
  result: CaptureEventResult<T>;
  constructor(id: CaptureEventIds, type: CaptureEventTypes, value: T, handle?: number) {
    // set result to error code if present in the value. Otherwise default to 0.
    let res = id === CaptureEventIds.Error ? value as unknown as number : 0;
    this.result = new CaptureEventResult<T>(id, type, res, value, handle);
  }
};

export class JRpcEventDevicePresence extends JRpcEvent<DeviceInfo> {
  constructor(id: CaptureEventIds, deviceInfo: DeviceInfo, handle?: number) {
    super(id, CaptureEventTypes.DeviceInfo, deviceInfo, handle);
  }
};

export class JRpcEventDiscoveredDevice extends JRpcEvent<DiscoveredDeviceInfo> {
  constructor(id: CaptureEventIds, discoveredDeviceInfo: DiscoveredDeviceInfo) {
    super(id, CaptureEventTypes.Object, discoveredDeviceInfo);
  }
};

export class JRpcRequest<T> extends JsonRpc {
  method: string;
  params?: T;
  constructor(id: number, method: string, params: T) {
    super(id);
    this.method = method;
    if(params && params !== null) {
      this.params = params;
    }
  }
};

export class JRpcResponse<T> extends JsonRpc {
  result?: T;
  constructor(id: number, response: T) {
    super(id);
    this.result = response;
  }
};

export class JRpcError extends JsonRpc {
  error: {
    code: number,
    message?: string
  }
  constructor(id: number, code: number, message?: string) {
    super(id);
    this.error = { code, message };
  }
};
